 function formProgress(kind){
  const schema=catalog.forms[kind],people=schema.needs_subject?(state.data.subjects[kind]||[]):[{id:'site'}];
  if(state.data.prior_assessments?.[kind])return{done:true,text:'PRIOR'};
  if(!people.length)return{done:false,text:'대상자 등록'};
  let completed=0,answered=0,changed=false;
  for(const person of people){const saved=state.data.assessments[kind+':'+person.id],local=drafts.get(row.public_id+'|'+period+'|'+kind+'|'+person.id),data=local?.data||saved?.draft?.data;changed||=!!local?.changed;if(saved?.completed&&sameData(data,saved.completed.data))completed++;answered+=schema.criteria.filter(q=>data?.answers?.[q.id]?.value!=null).length;}
  const done=completed===people.length&&!changed;
  return{done,text:done?'완료':'입력 '+answered+' / '+schema.criteria.length*people.length};
 }
