 function assessmentStamp(value,kind,target){const canonical=v=>Array.isArray(v)?v.map(canonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):v;return JSON.stringify(canonical(value?.data?.assessments[kind+':'+target]?.draft?.data??null));}
